#include <iostream>
#include <string>
#include <limits>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');

    int balance = 0;
    bool valid = true;

    for (int i = 0; i < N; ++i) {
        string line;
        getline(cin, line);
        for (char c : line) {
            if (c == '{') {
                ++balance;
            } else if (c == '}') {
                --balance;
                if (balance < 0) {
                    valid = false;
                }
            }
        }
    }

    if (valid && balance == 0) {
        cout << "S\n";
    } else {
        cout << "N\n";
    }

    return 0;
}
